function handleCellInput(cell) {
    let newValue = cell.innerText.trim();
    const cellCoordinates = cell.dataset.cell;

    if (!cellCoordinates || !newValue) {
        console.log(`[Evento de entrada detectado] Celda ${cellCoordinates} vacía o sin coordenadas.`);
        return;
    }

    console.log(`[Evento de entrada detectado] Celda ${cellCoordinates} actualizada a: "${newValue}"`);

    // 1. Detectar si es una fórmula y procesarla
    if (newValue.startsWith('=')) {
        try {
            const result = evaluateFormula(cell, newValue);
            if (result !== null) {
                // Mostrar el resultado calculado en lugar de la fórmula
                cell.innerText = String(result);
                console.log(`Cálculo exitoso para ${cellCoordinates}. Resultado: ${result}`);
                return; // Salir después de calcular y actualizar la celda
            }
        } catch (e) {
            // Si hay un error en el cálculo, dejar visible la fórmula o mostrar #ERROR
            console.error(`Error al evaluar la fórmula en ${cellCoordinates}:`, e);
        }
    }

    // 2. Si no es una fórmula, solo confirmar y mantener el valor ingresado.
    if (newValue) {
        console.log(`Valor capturado exitosamente para ${cellCoordinates}.`);
    } else {
        console.log(`Celda ${cellCoordinates} vacía.`);
    }
}

/**
 * Evalúa una fórmula simple de hoja de cálculo basada en las coordenadas y el contenido actual de la grilla.
 * Maneja SUMA(rango) y operaciones básicas (-, *, /).
 * Nota: Esta es una implementación muy simplificada para resolver el problema del requisito R3.
 * @param {HTMLElement} callingCell - La celda donde se está escribiendo la fórmula.
 * @param {string} formulaString - El contenido de la fórmula (ej: "=SUMA(A1:A3)").
 * @returns {number | null} El resultado del cálculo o null si falla.
 */
function evaluateFormula(callingCell, formulaString) {
    // Normalizamos el formato para facilitar el parsing interno
    let workingFormula = formulaString.toUpperCase().replace(/ /g, '');

    // --- Caso 1: Suma de rangos (SUMA(A1:A3)) ---
    const sumMatch = workingFormula.match(/^=SUMA\(([A-Z]+,\s*\d+)\s*:\s*([A-Z]+),\s*(\d+)[\)]/);
    if (sumMatch) {
        // Los grupos capturados son: 1: ColInicio, RowInicio; 2: ColFin, RowFin
        const startCoordsStr = sumMatch[1].split(';'); // Ej: A, 1
        const endCoordsStr = sumMatch[2] + ',' + sumMatch[3]; // Ej: A, 3

        if (startCoordsStr.length < 2 || !endCoordsStr) return null;

        // Extraer coordenadas de inicio y fin
        const startCol = startCoordsStr[0].trim();
        const startRow = parseInt(startCoordsStr[1].trim());
        const endCol = endCoordsStr.charAt(0);
        const endRow = parseInt(endCoordsStr.split(',')[1].trim());

        if (isNaN(startRow) || isNaN(endRow)) return null;

        let totalSum = 0;
        // Iterar sobre todas las celdas en el rango [startCol:endCol] y [startRow:endRow]
        for (let r = startRow; r <= endRow; r++) {
            for (let i = startCol.charCodeAt(0); i <= endCol.charCodeAt(0); i++) {
                const colChar = String.fromCharCode(i);
                // Intentar encontrar la celda correspondiente en el DOM. 
                // Asumimos que las coordenadas son absolutas y se encuentran dentro de la grilla.
                const targetCellSelector = `[data-cell*="${{${colChar}, ${r}}"]`;
                const targetCell = document.querySelector(targetCellSelector);

                if (targetCell) {
                    // Solo suma si el contenido es numérico o está vacío (tratado como 0)
                    let value = parseFloat(targetCell.innerText.replace(/[^0-9.-]/g, ''));
                    if (!isNaN(value)) {
                        totalSum += value;
                    } else if (targetCell.innerText === '') {
                         // Si está vacío y no es el caso de fórmula, lo tratamos como 0 para la suma.
                    }
                }
            }
        }
        return totalSum;
    }

    // --- Caso 2: Operaciones simples (A1-B1) ---
    try {
        let expression = workingFormula.replace(/=/, ''); // Quitar '=' inicial
        // Esta es la parte más compleja de simular sin un parser completo.
        // Intentaremos reemplazar referencias de coordenadas con valores numéricos.

        // Expresión regular para encontrar patrones de celda como A1, B2, etc.
        const cellRegex = /([A-Z]+,\s*\d+)/g; 
        expression = expression.replace(cellRegex, (match) => {
            // Extraer Columna y Fila del match "A, 1"
            const coords = match.toUpperCase().split(',').map(s => s.trim());
            if (coords.length < 2) return '0';

            const colChar = coords[0].charAt(0);
            const rowNum = parseInt(coords[1]);

            // Intentar obtener el valor de la celda referenciada en el DOM
            const targetCellSelector = `[data-cell*="${{${colChar}, ${rowNum}}"]`;
            const targetCell = document.querySelector(targetCellSelector);

            if (targetCell) {
                let value = parseFloat(targetCell.innerText.replace(/[^0-9.-]/g, ''));
                return isNaN(value) ? 0 : value; // Si no se puede parsear, usar 0 por seguridad.
            } else {
                return 0; // Celda inexistente o vacía tratada como 0
            }
        });

        // Evaluar la expresión matemática resultante (Ej: "2-3*4")
        const result = eval(expression);
        return isNaN(result) ? null : Number(result.toFixed(2));

    } catch (e) {
        console.error("Error al evaluar fórmula aritmética:", e);
        return null;
    }
}
