### FUNCION: calculateCoordinates
```js
/**
 * Convierte una coordenada de estilo Excel (ej: 'A1') en un objeto {row, col}.
 * @param {string} coord - La coordenada a convertir.
 * @returns {{row: number, col: number}|null} Objeto con índice de fila y columna (base 0).
 */
function calculateCoordinates(coord) {
    if (!coord || typeof coord !== 'string') return null;

    const match = coord.toUpperCase().match(/^([A-Z]+)([1-9]\d*)$/);
    if (!match) return null;

    let colStr = match[1];
    let rowStr = match[2];

    // Calcular la columna (A=0, B=1, ...)
    let col = 0;
    for (let i = 0; i < colStr.length; i++) {
        col = col * 26 + (colStr.charCodeAt(i) - 'A'.charCodeAt(0) + 1);
    }
    const finalCol = col - 1;

    // Calcular la fila (índice 0-based)
    const row = parseInt(rowStr, 10) - 1;

    return { row: row, col: finalCol };
}
```

### FUNCION: getValueFromCoord
```js
/**
 * Obtiene el valor de una celda dada su coordenada (ej: 'A1').
 * @param {string} coord - La coordenada.
 * @returns {number|string|null} El valor numérico o string, o null si no se encuentra.
 */
function getValueFromCoord(coord) {
    const coords = calculateCoordinates(coord);
    if (!coords) return null;

    // Buscamos el elemento TD que corresponde a la coordenada en el DOM
    const rowElement = document.querySelector(`tbody tr:nth-child(${coords.row + 1})`);
    if (!rowElement) return null;

    const colIndex = coords.col;
    const cellElement = rowElement.querySelector('td:nth-child(' + (colIndex + 1) + ')');

    if (cellElement && cellElement.dataset.cell === coord) {
        const value = cellElement.innerText.trim();
        // Si es un número, lo retornamos como number para el cálculo; si no, como string.
        return isNaN(parseFloat(value)) || value === "" ? value : parseFloat(value);
    }

    return null; // Celda no encontrada o fuera de rango
}
