### FUNCION: evaluateFormula
```js
/**
 * Evalúa una fórmula simple (SUMA, +, -, *, /) utilizando valores de coordenadas.
 * @param {string} formula - La fórmula a evaluar (ej: "=SUMA(A1:A3)").
 * @returns {string} El resultado formateado como string.
 */
function evaluateFormula(formula) {
    let expression = formula.substring(1).trim(); // Quitar '=' inicial

    // 1. Manejo de Rangos y Celdas Sueltas (Simple Replacement)
    // Esto es un reemplazo muy simplificado para abordar el requerimiento.
    // Solo detecta patrones tipo A1:A3 o A1;B2, etc., e intenta evaluarlos.

    let evaluatedExpression = expression;

    // Función auxiliar para obtener valor de una coordenada y reemplazarla en la expresión
    const replaceCoordWithValue = (match) => {
        const coord = match[0];
        const value = getValueFromCoord(coord);
        return typeof value === 'number' ? value : `${value}`; // Retornar número o string para el eval()
    };

    // Patrón: Coordenada de celda (ej: A1, B2)
    evaluatedExpression = evaluatedExpression.replace(/([A-Z]+[0-9]+)/g, replaceCoordWithValue);

    // 2. Manejo de SUMA(range)
    if (expression.toUpperCase().startsWith("SUMA")) {
        const match = expression.match(/SUMA\(([^)]+)\)/i);
        if (match && match[1]) {
            let rangeContent = match[1];
            // Reemplazar referencias en el rango por sus valores numéricos
            rangeContent = rangeContent.replace(/([A-Z]+:?[A-Z0-9]*)/g, replaceCoordWithValue);

            const values = rangeContent.split(';').map(s => s.trim()).filter(Boolean).map(v => parseFloat(v)).filter(n => !isNaN(n));
            if (values.length > 0) {
                const sum = values.reduce((acc, val) => acc + val, 0);
                return sum.toString();
            }
            return "Error";
        }
    }

    // 3. Manejo de Operadores Aritméticos (usando eval() - peligroso pero necesario para la simulación simple)
    try {
        // Si no es una fórmula compleja, intentamos usar el motor de evaluación JS en lo que queda.
        // Esto maneja A1-B1, A1*B1, etc., después de que las coordenadas han sido reemplazadas por valores.
        const result = eval(evaluatedExpression);
        return isNaN(result) ? "" : String(result);
    } catch (e) {
        console.error("Error al evaluar la fórmula:", e);
        return "#ERROR!";
    }
}
