/**
 * Función auxiliar para evaluar fórmulas simples de la hoja de cálculo.
 * Soporta =SUMA(Rango) y operadores básicos (-, *, /).
 * @param {string} formulaString - La cadena de fórmula ingresada, debe empezar con '='.
 * @returns {number | null} El resultado numérico calculado o null si falla el parsing/cálculo.
 */
function calculateFormula(formulaString) {
    // Eliminar el signo = inicial para procesamiento
    let formula = formulaString.substring(1).trim();

    try {
        if (formula.toUpperCase().startsWith('SUMA')) {
            // Caso: SUMA(Rango o Celdas sueltas)
            const sumMatch = formula.match(/SUMA\(([^)]+)\)/i);
            if (!sumMatch || !sumMatch[1]) return null;

            let referencesString = sumMatch[1];

            // Separar rangos y celdas sueltas (ej: A1:A3, B2, C4)
            const parts = referencesString.split(',');
            let totalSum = 0;

            for (const part of parts) {
                const trimmedPart = part.trim();
                if (!trimmedPart) continue;

                // Si es un rango (A1:A3)
                if (trimmedPart.includes(':')) {
                    const rangeCoords = trimmedPart.split(':');
                    let rangeSum = 0;
                    for (const coord of rangeCoords) {
                        rangeSum += getCellValue(coord.trim());
                    }
                    totalSum += rangeSum;
                } else {
                    // Es una celda suelta (A1)
                    totalSum += getCellValue(trimmedPart);
                }
            }
            return parseFloat(totalSum.toFixed(2));

        } else if (formula.match(/^[A-Z]+[0-9]+\s*[+\-*/]\s*[A-Z]+[0-9]+$/i)) {
             // Caso: Operaciones aritméticas simples (ej: A1-B1)
            const parts = formula.match(/[A-Z]+[0-9]+/g);
            if (!parts || parts.length < 2) return null;

            let expression = formula;

            // Reemplazar referencias de coordenadas por sus valores numéricos para evaluación matemática segura
            expression = expression.replace(/([A-Z]+[0-9]+)/gi, (coord) => {
                const value = getCellValue(coord);
                return isNaN(value) ? '0' : value; // Usar 0 si no se encuentra o es inválido
            });

            // Evaluar la expresión matemática resultante (EJ: "2-3")
            return eval(expression);
        }

    } catch (e) {
        console.error("Error al evaluar fórmula:", e);
        return null;
    }
    return null;
}

/**
 * Obtiene el valor numérico de una celda dado su código (ej: "A1").
 * @param {string} coord - La coordenada de la celda (Columna y Fila).
 * @returns {number} El valor numérico o 0 si no se encuentra/es inválido.
 */
function getCellValue(coord) {
    // Intentar encontrar el elemento TD correspondiente a las coordenadas
    const match = coord.match(/([A-Z]+)([0-9]+)/);
    if (!match) return NaN;

    const colLetter = match[1];
    const rowNumber = parseInt(match[2]);

    // Buscar el elemento en la hoja de cálculo por su data-cell attribute: (Col, Row)
    let cellElement = null;
    document.querySelectorAll('#spreadsheet-grid tbody td').forEach(td => {
        if (td.dataset.cell === `(${colLetter}, ${rowNumber})`) {
            cellElement = td;
        });
    });

    if (cellElement) {
        const text = cellElement.innerText.trim();
        // Si el contenido parece un número, lo devolvemos como tal. 
        // Si es una fórmula o texto, se intenta parsear pero si no funciona, devuelve NaN para que la evaluación de fórmulas falle correctamente.
        const value = parseFloat(text);
        return isNaN(value) ? 0 : value; // Devolver 0 si el valor está vacío o no es numérico (para evitar errores en cálculos).
    }

    // Si la celda no existe
    return NaN;
}
