 * @param {string} coordinates - Coordenadas en formato (Columna, Fila).
 * @returns {(number|string)|null} El valor de la celda.
 */
function getCellValue(coordinates) {
    // Limpia coordenadas para asegurar el selector correcto: A, 1 -> td[data-cell="(A, 1)"]
    const cellSelector = `td[data-cell="${coordinates}"]`;
    const element = document.querySelector(cellSelector);

    if (!element) {
        console.warn(`Celda ${coordinates} no encontrada.`);
        return null;
    }

    // Obtenemos el texto visible, que podría ser el resultado o la fórmula si aún no se ha calculado.
    let content = element.innerText.trim();

    if (!content) return null;

    // Si parece un número (y no es una fórmula), lo parseamos como tal para cálculos posteriores.
    const numValue = parseFloat(content);
    return isNaN(numValue) ? (typeof content === 'string' && content.startsWith('=') ? content : content) : numValue;
}

/**
 * Intenta calcular y actualizar el contenido de una celda si contiene una fórmula.
 * @param {HTMLElement} cell - La celda a evaluar.
 */
function calculateCellFormula(cell) {
    const cellCoordinates = cell.dataset.cell;
    if (!cellCoordinates) return false;

    let formulaString = cell.innerText.trim();

    // 1. Verifica si el contenido es una fórmula (empieza con '=')
    if (formulaString && typeof formulaString === 'string' && formulaString.startsWith('=')) {
        try {
            let expression = formulaString.substring(1); // Elimina '='

            // 2. Reemplaza referencias de celda (ej: A, 1) con sus valores reales.
            expression = expression.replace(/([A-Z]+,\s*\d+)/g, (match) => {
                const value = getCellValue(match);
                // Aseguramos que el valor reemplazado sea una cadena numérica para eval() o un string literal si no es numérico.
                if (typeof value === 'number') return String(value);
                return typeof value === 'string' ? `'${value}'` : '0'; 
            });

            let result;
            // Usamos Function constructor de forma segura para evaluar la expresión matemática.
            result = new Function('return ' + expression)();

            if (!isNaN(result)) {
                // Actualizamos el contenido visible con el resultado calculado.
                cell.innerText = result.toString();
                console.log(`[Cálculo] Celda ${cellCoordinates} recalculada a: ${result}`);
                return true; // Cálculo exitoso y valor actualizado
            } else {
                 console.warn(`No se pudo calcular la fórmula de ${cellCoordinates}.`);
                 return false;
            }

        } catch (e) {
            console.error("Error al evaluar fórmula:", e);
            return false;
        }
    }
    return true; // No es una fórmula o no se pudo calcular
}

/**
