/**
 * Alterna la visibilidad de una columna seleccionada, ocultando o mostrando contenido y selectores.
 * @param {boolean} hide - True para ocultar, False para mostrar.
 */
function toggleColumnVisibility(hide) {
    const colInfo = getSelectedColumnInfo();
    if (!colInfo) return;

    const columnIndex = colInfo.index;
    const gridBody = document.querySelector('#spreadsheet-grid tbody');
    const headerRow = document.querySelector('#spreadsheet-grid thead tr');

    // 1. Ocultar/Mostrar celdas de datos en el body
    const dataCells = document.querySelectorAll(`[data-col-index="${columnIndex}"]`);
    dataCells.forEach(cell => {
        if (hide) {
            cell.style.display = 'none'; // Oculta la celda completa
        } else {
            cell.style.display = ''; // Muestra la celda
        }
    });

    // 2. Ocultar/Mostrar el encabezado de columna (TD en thead)
    const headerCells = headerRow ? Array.from(headerRow.children) : [];
    let headerCell = headerCells[columnIndex];

    if (headerCell) {
        if (hide) {
            // Ocultar tanto la celda como su selector visual
