            }
        }
    }

    // 3. Ocultar/Mostrar el selector de columna en la cabecera (el elemento <th class="column-selector selected">)
    const selectorHeader = document.querySelector('.column-selector.selected');
    if (selectorHeader) {
         if (hide) {
            selectorHeader.style.display = 'none'; 
        } else {
            selectorHeader.style.display = ''; 
        }
    }

    // Actualizar estados visuales y de botón después de la acción
    updateColumnSelectionState();
