 */
function hideSelectedColumn() {
    const colInfo = getSelectedColumnInfo();
    if (!colInfo) return;

    const columnIndex = colInfo.index;

    // 1. Ocultar celdas de datos (TDs) y contenido
    document.querySelectorAll(`[data-col-index="${columnIndex}"]`).forEach(cell => {
        cell.style.display = 'none';
        cell.textContent = ''; // Limpiar texto visiblemente
    });

    // 2. Ocultar el encabezado de la columna (TH en thead) y contenido
    const headerCells = document.querySelector('#spreadsheet-grid thead tr').children;
    if (headerCells[columnIndex]) {
         headerCells[columnIndex].style.display = 'none';
         headerCells[columnIndex].textContent = ''; // Limpiar texto visiblemente
    }

    // 3. Deseleccionar y limpiar controles
    document.querySelectorAll('.column-selector').forEach(h => h.classList.remove('selected'));
    document.getElementById('spreadsheet-grid').querySelectorAll('tbody td, th').forEach(cell => {
        cell.classList.remove('column-selected');
    });
    clearActionButtons();

    console.log(`Columna ${colInfo.letter} oculta con éxito.`);
}
