/**
 * Oculta completamente la fila que contiene el row-header seleccionado, incluyendo su contenido y cabecera.
 */
function handleRowHide() {
    const selectedHeader = document.querySelector('.row-header.selected');
    if (!selectedHeader) {
        console.warn("No hay fila seleccionada para ocultar.");
        return;
    }

    // El elemento padre del row-header es el <tr> de la fila completa
    const targetRow = selectedHeader.closest('tr');
    if (targetRow) {
        // Ocultar estructuralmente y visualmente
        targetRow.style.display = 'none';
        selectedHeader.classList.remove('selected');
        console.log(`Fila ${selectedHeader.textContent} oculta con éxito.`);

        // Deshabilitar botones de control si la grilla está vacía o incompleta (opcional)
    } else {
         console.error("Error: No se pudo encontrar el contenedor de fila (<tr>) para la cabecera seleccionada.");
    }
}
