/**
 * Guarda el valor de una celda específica en localStorage.
 * @param {string} coordinates - Coordenadas de la celda (ej: "B2").
 * @param {string} value - El valor actual del contenido.
 */
function saveCellValue(coordinates, value) {
    const storage = window.localStorage;
    let data = JSON.parse(storage.getItem('spreadsheetData')) || {};
    data[coordinates] = value;
    storage.setItem('spreadsheetData', JSON.stringify(data));
}

/**
 * Carga todos los datos de las celdas desde localStorage y los aplica a la grilla.
 */
function loadSheetState() {
    const storedDataString = window.localStorage.getItem('spreadsheetData');
    if (!storedDataString) return;

    const storedData = JSON.parse(storedDataString);
    const dataCells = document.querySelectorAll('#spreadsheet-grid tbody td');

    let cellsUpdatedCount = 0;

    dataCells.forEach(cell => {
        const coordinates = cell.dataset.cell;
        if (storedData[coordinates] !== undefined) {
            const value = storedData[coordinates];
            // Restaura el texto en la celda y actualiza su contenido DOM
            cell.textContent = value;
            cellsUpdatedCount++;
        } else {
             // Asegurarse de que los elementos vacíos estén limpios si no hay datos guardados
             cell.textContent = '';
        }
    });

    console.log(`[Persistencia] ${cellsUpdatedCount} celdas restauradas desde localStorage.`);
}
