### FUNCION: loadSpreadsheetState
```js
function loadSpreadsheetState() {
    const savedState = localStorage.getItem('spreadsheetState');
    if (!savedState) {
        console.log("No se encontraron datos guardados en el almacenamiento local.");
        return;
    }

    try {
        const state = JSON.parse(savedState);
        let restoredCount = 0;

        state.forEach(item => {
            // Buscar la celda por sus atributos de datos (ej: data-cell="A1")
            const cellElement = document.querySelector(`[data-cell="${item.coordinates}"]`);
            if (cellElement) {
                // Restaurar el contenido sin modificar los listeners o la estructura interna
                cellElement.innerText = item.value;
                restoredCount++;
            } else {
                console.warn(`No se encontró la celda para las coordenadas: ${item.coordinates}`);
            }
        });

        console.log(`Estado restaurado exitosamente. Se recuperaron ${restoredCount} celdas.`);

    } catch (e) {
        console.error("Error al cargar el estado de la hoja de cálculo:", e);
    }
}
