### FUNCION: saveSpreadsheetState
```js
function saveSpreadsheetState() {
    const editableCells = document.querySelectorAll('.spreadsheet-grid td[contenteditable="true"]');
    let state = [];

    editableCells.forEach(cell => {
        // Asumimos que las celdas editables tienen el data-cell con la coordenada A1
        const coordinates = cell.dataset.cell; 
        const value = cell.innerText.trim();
        state.push({
            coordinates: coordinates,
            value: value
        });
    });

    localStorage.setItem('spreadsheetState', JSON.stringify(state));
    console.log("Estado de la hoja de cálculo guardado exitosamente en localStorage.");
}
